--
-- Table structure for table `incident_email_messages`
--

DROP TABLE IF EXISTS `incident_email_messages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `incident_email_messages` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `thread_id` bigint DEFAULT NULL,
  `incident_id` int NOT NULL,
  `direction` enum('outbound','inbound') COLLATE utf8mb4_unicode_ci NOT NULL,
  `action_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `graph_message_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `internet_message_id` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subject` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sender` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recipients` text COLLATE utf8mb4_unicode_ci,
  `cc_recipients` text COLLATE utf8mb4_unicode_ci,
  `body_preview` text COLLATE utf8mb4_unicode_ci,
  `status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `error_details` text COLLATE utf8mb4_unicode_ci,
  `occurred_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_incident_email_graph_message` (`graph_message_id`),
  KEY `idx_incident_email_messages_incident` (`incident_id`,`occurred_at`),
  KEY `fk_incident_email_messages_thread` (`thread_id`),
  KEY `fk_incident_email_messages_user` (`created_by`),
  CONSTRAINT `fk_incident_email_messages_incident` FOREIGN KEY (`incident_id`) REFERENCES `incidents` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_incident_email_messages_thread` FOREIGN KEY (`thread_id`) REFERENCES `incident_email_threads` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_incident_email_messages_user` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3248 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
